head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[video > P > poster]<br/>Video 컴포넌트에서 동영상이 재생되기 전 표시할 이미지를 URL 로 설정합니다.",
    "validation" : [
        "동영상이 재생되기 전 표시할 이미지 파일의 URL 을 설정합니다.",
        "상대경로, 절대경로, 프로토콜 포함 경로를 설정할 수 있습니다.",
        "PNG, JPG, JPEG, GIF, SVG 등 웹브라우저가 지원하는 모든 이미지 파일을 설정할 수 있습니다.",
        "poster 속성값을 출력 HTML 의 video 태그에 전달하며, 실제 동작은 브라우저의 HTML5 video 처리에 따라 결정됩니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// poster 는 로드 성공 여부를 알려주는 이벤트/프로퍼티가 없으므로 동일 URL 을 Image 로 로드하여 판정
scwin.fn_isImageLoaded = function (sUrl) {
    return new Promise(function (resolve) {
        let oImage = new Image();
        oImage.onload = function () { resolve(true); };
        oImage.onerror = function () { resolve(false); };
        oImage.src = sUrl;
    });
};



// 재생 전 poster 이미지 표시 여부와 출력 HTML video 태그로 전달된 poster 속성값 확인
scwin.btn_getPoster_onclick = async function (e) {
    let el1 = document.querySelector("#target1");
    let bLoaded = await scwin.fn_isImageLoaded(el1.poster);

    wf_body_bottom.getObj("scwin").setReturnValue("재생 전 표시할 이미지 - target1 poster 이미지 로드 : " + bLoaded + " , 재생 전 상태(paused) : " + el1.paused);
    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML video 태그 전달 - target1 poster 속성값 : " + JSON.stringify(el1.getAttribute("poster")));
};



// 절대경로 / 상대경로 / 프로토콜 포함 경로별 poster 설정 및 로드 결과 확인
// 프로토콜 포함 경로는 실행 환경마다 호스트/포트가 달라 XML 에 하드코딩하지 않고 location.origin 으로 조립
scwin.btn_getPosterPath_onclick = async function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    el3.poster = location.origin + "/img/png.png";

    let bAbsolute = await scwin.fn_isImageLoaded(el1.poster);
    let bRelative = await scwin.fn_isImageLoaded(el2.poster);
    let bProtocol = await scwin.fn_isImageLoaded(el3.poster);
    let bSameUrl = (el1.poster === el2.poster) && (el2.poster === el3.poster);

    wf_body_bottom.getObj("scwin").setReturnValue("경로 3형태(절대 -> 상대 -> 프로토콜 포함) - 이미지 로드 : " + bAbsolute + " -> " + bRelative + " -> " + bProtocol + " , 해석된 절대 URL 동일 : " + bSameUrl);
};



// PNG / JPG / GIF / SVG 형식별 poster 이미지 로드 결과 확인
scwin.btn_getPosterFormat_onclick = async function (e) {
    let bPng = await scwin.fn_isImageLoaded(document.querySelector("#target1").poster);
    let bJpg = await scwin.fn_isImageLoaded(document.querySelector("#target4").poster);
    let bGif = await scwin.fn_isImageLoaded(document.querySelector("#target5").poster);
    let bSvg = await scwin.fn_isImageLoaded(document.querySelector("#target6").poster);

    wf_body_bottom.getObj("scwin").setReturnValue("이미지 형식(PNG -> JPG -> GIF -> SVG) - 이미지 로드 : " + bPng + " -> " + bJpg + " -> " + bGif + " -> " + bSvg);
};
